import React,{useEffect,useMemo,useState} from 'react';
import {LayoutDashboard,Table2,Layers3,ReceiptText,Search,History,Settings,Plus,Download,Upload,Filter,ArrowUpDown,RefreshCw,LogOut,Menu,X,Check,CheckCircle2,AlertCircle,Trash2,Pencil,Save,MoveRight,ChevronLeft,ChevronRight,Copy,FileSpreadsheet,Package2,ShieldCheck,CalendarDays,MapPin,Boxes,Wallet,Eye,Lock,Info,ArrowRight,Database} from 'lucide-react';
import {STATUSES,STATUS_NAMES,PROCESSES,PROCESS_NAMES,today,money,dateLabel,itemTotal,matches,sortMaterials,toCsv,parseExcel,id,isReceivedMaterial,blockStage} from './domain.js';
import {cloud,supabase,loadAll,getRole,saveRow,deleteRow,setMaterialStatus,moveMaterials,saveManyMaterials,saveInvoice,deleteInvoice,mergeView,autoGroupMaterials,getDatabaseUsageBytes,closeBlock,reorderBlocks} from './store.js';

import {downloadWorkbook} from './excel.js';

const menu=[{id:'dashboard',name:'Visão geral',icon:LayoutDashboard},{id:'records',name:'Lançamentos',icon:Table2},{id:'blocks',name:'Blocos',icon:Layers3},{id:'invoices',name:'Notas fiscais',icon:ReceiptText},{id:'lookup',name:'Consulta SAP / Forms',icon:Search},{id:'activity',name:'Histórico',icon:History},{id:'settings',name:'Configurações',icon:Settings}];
const EMPTY_FILTERS={search:'',status:'',process:'',site_id:'',from:'',to:'',invoice:'',min_value:'',max_value:''};
const SORTS=[['recent','Mais recentes'],['oldest','Mais antigos'],['date_desc','Data (recente)'],['date_asc','Data (antiga)'],['sap','Código SAP'],['forms','Forms'],['description','Descrição'],['value_desc','Maior valor'],['value_asc','Menor valor'],['status','Status'],['quantity_desc','Maior quantidade'],['quantity_asc','Menor quantidade'],['unit_desc','Maior preço unitário'],['unit_asc','Menor preço unitário'],['site','Site / fábrica'],['process','Processo']];
const FIELDS=['sap_code','forms_code','description','process','quantity','unit_price','site_id','requested_on','status','block_id','notes','auto_group_on_insert'];
const cleanMaterial=row=>({...Object.fromEntries(FIELDS.map(k=>[k,row[k]]).filter(([,v])=>v!==undefined)),...(row.id?{id:row.id}:{})});

function Button({children,icon:Icon,variant='primary',small=false,disabled=false,onClick,type='button',className=''}){
 return <button type={type} disabled={disabled} onClick={onClick} className={`btn btn-${variant} ${small?'btn-sm':''} ${className}`}>{Icon&&<Icon size={small?14:17}/>}<span>{children}</span></button>;
}
function Field({label,children,hint}){return <label className="field"><span className="field-label">{label}</span>{children}{hint&&<span className="field-hint">{hint}</span>}</label>}
function TextInput({value,onChange,...rest}){return <input {...rest} value={value??''} onChange={e=>onChange(e.target.value)}/>}
function Select({value,onChange,children,...rest}){return <select {...rest} value={value??''} onChange={e=>onChange(e.target.value)}>{children}</select>}
function Opts({items,blank='Todos'}){return <><option value="">{blank}</option>{items.map(([key,label])=><option value={key} key={key}>{label}</option>)}</>}
function Status({value}){return <span className={`status status-${value||'rascunho'}`}><span className="status-dot"/>{STATUS_NAMES[value]||value||'—'}</span>}
function Pill({children}){return <span className="pill">{children}</span>}
function Empty({icon:Icon=Boxes,title='Nenhum registro encontrado',description='Cadastre o primeiro item ou ajuste os filtros.',action}){return <div className="empty"><div className="empty-icon"><Icon size={26}/></div><strong>{title}</strong><span>{description}</span>{action}</div>}
function Modal({title,onClose,children,wide=false}){useEffect(()=>{const h=e=>{if(e.key==='Escape')onClose();};window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h)},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'modal-wide':''}`}><div className="modal-top"><h2>{title}</h2><button className="icon-button" onClick={onClose} title="Fechar"><X size={20}/></button></div><div className="modal-body">{children}</div></div></div>}
function Heading({eyebrow,title,description,actions}){return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description&&<p>{description}</p>}</div>{actions&&<div className="heading-actions">{actions}</div>}</div>}
function Subhead({title,description,actions}){return <div className="subhead"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div>{actions&&<div className="subhead-actions">{actions}</div>}</div>}
function ExportButton({rows}){return <Button variant="secondary" icon={Download} small onClick={()=>{const data=toCsv(rows);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'}));a.download=`notaflow-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}}>Exportar CSV</Button>}
function ExcelExport({filters,sort='recent',invoiceSearch=''}){
 const [open,setOpen]=useState(false),[working,setWorking]=useState(false),[error,setError]=useState('');
 const download=async filtered=>{setWorking(true);setError('');try{const raw=await loadAll();await downloadWorkbook(raw,{filtered,filters,sort,invoiceSearch});setOpen(false);}catch(e){setError(e.message||'Falha ao exportar Excel.');}finally{setWorking(false);}};
 return <><Button variant="secondary" small icon={Download} onClick={()=>setOpen(true)}>Exportar Excel</Button>{open&&<Modal title="Exportar Excel" onClose={()=>{if(!working)setOpen(false);}}><p className="muted">O relatório inclui materiais, notas fiscais e resumo geral. A opção filtrada considera todos os resultados dos filtros, em todas as páginas. Totais da aba Notas fiscais consideram os materiais exportados.</p><div className="modal-actions"><Button disabled={working} onClick={()=>download(false)}>Exportar Excel completo</Button><Button variant="secondary" disabled={working} onClick={()=>download(true)}>Exportar Excel filtrado</Button></div>{working&&<p role="status">Preparando relatório. Aguarde…</p>}{error&&<p role="alert" className="error-text">{error}</p>}</Modal>}</>;
}
function Filters({value,set,sites,invoice=false,compact=false,showSort=false,sort,setSort}){
 const update=(key,v)=>set(p=>({...p,[key]:v}));
 return <div className={`filters-wrap ${compact?'filters-compact':''}`}>
  <div className="filters">
   <div className="search-field"><Search size={17}/><TextInput aria-label="Pesquisar SAP, Forms ou descrição" placeholder="Buscar SAP, Forms, descrição, site..." value={value.search} onChange={v=>update('search',v)}/></div>
   <Select aria-label="Filtrar situação" value={value.status} onChange={v=>update('status',v)}><Opts items={STATUSES.map(s=>[s,STATUS_NAMES[s]])} blank="Todas as situações"/></Select>
   <Select aria-label="Filtrar processo" value={value.process} onChange={v=>update('process',v)}><Opts items={PROCESSES.map(s=>[s,PROCESS_NAMES[s]])} blank="CNC / 3D / Todos"/></Select>
   <Select aria-label="Filtrar site" value={value.site_id} onChange={v=>update('site_id',v)}><Opts items={sites.map(s=>[s.id,s.name])} blank="Todos os sites"/></Select>
   {invoice&&<Select aria-label="Filtrar vínculo de nota" value={value.invoice} onChange={v=>update('invoice',v)}><Opts items={[["with","Com nota"],["without","Sem nota"]]} blank="Todas as notas"/></Select>}
  </div>
  <div className="filters-extras">
   <label>Valor mínimo (R$) <TextInput aria-label="Valor total mínimo" inputMode="decimal" type="number" min="0" step="0.01" value={value.min_value} onChange={v=>update('min_value',v)} placeholder="0,00"/></label>
   <label>Valor máximo (R$) <TextInput aria-label="Valor total máximo" inputMode="decimal" type="number" min="0" step="0.01" value={value.max_value} onChange={v=>update('max_value',v)} placeholder="Sem limite"/></label>
   <label>De <TextInput aria-label="Data inicial" type="date" value={value.from} onChange={v=>update('from',v)}/></label>
   <label>Até <TextInput aria-label="Data final" type="date" value={value.to} onChange={v=>update('to',v)}/></label>
   {showSort&&<label>Ordenar por <Select aria-label="Ordenar materiais" value={sort} onChange={setSort}>{SORTS.map(([k,v])=><option key={k} value={k}>{v}</option>)}</Select></label>}
   <button type="button" className="clear-filters" onClick={()=>set({...EMPTY_FILTERS})}>Limpar filtros</button>
  </div>
 </div>;
}
function ProcessTag({process}){return <span className={`process-label process-label-${process==='cnc'?'cnc':process==='3d'?'3d':'other'}`}>{PROCESS_NAMES[process]||'Não definido'}</span>}
function BlockPanel({block,members,rows,selected,setSelected,canWrite,busy,onEdit,onRename,onClose,onShift,canMoveUp,canMoveDown,onStatus,onInvoice}){
 const [status,setStatus]=useState('solicitado');
 const processes=[...new Set(members.map(m=>m.process))];
 const pending=members.filter(m=>m.status==='rascunho'&&!m.invoice_id);
 const ready=members.filter(m=>m.status==='solicitado'&&!m.invoice_id);
 const received=members.filter(isReceivedMaterial).length;
 const stage=blockStage(members);
 const stageLabel=stage==='received'?'Pronto para encerrar':stage==='requested'?'Pedido no SAP':'Aguardando solicitação';
 return <section aria-label={block.name} className={`panel block-panel colored-block ${processes.length===1?`block-type-${processes[0]}`:processes.length>1?'block-type-mixed':''}`}>
  <div className="block-head">
   <div className="block-heading-main">
    <span className={`block-stage-label block-stage-${stage}`}>{block.id?stageLabel:'Organização manual'}</span>
    <h3>{block.name}</h3>
    <div className="block-processes">{processes.length>1&&<span className="mixed-label">Misto</span>}{processes.map(process=><ProcessTag key={process} process={process}/>)}</div>
    <span className="muted">{members.length}{block.id?'/4':''} material(is) · {money(members.reduce((sum,m)=>sum+itemTotal(m),0))}</span>
    {block.id&&<div className="block-stage-stats"><span className="stage-draft">{pending.length} A pedir</span><span className="stage-requested">{ready.length} Pedido</span>{received>0&&<span className="stage-invoiced">{received} com NF / concluído</span>}</div>}
   </div>
   {canWrite&&block.id&&<div className="block-card-controls">
    <div className="inline-buttons"><button disabled={busy||!canMoveUp} title="Mover bloco para cima" className="icon-button block-order-up" onClick={()=>onShift(block,-1)}><ChevronLeft size={17}/></button><button disabled={busy||!canMoveDown} title="Mover bloco para baixo" className="icon-button block-order-down" onClick={()=>onShift(block,1)}><ChevronRight size={17}/></button></div>
    <div className="inline-buttons"><button disabled={busy} title="Renomear bloco" className="icon-button" onClick={()=>onRename(block)}><Pencil size={17}/></button><button disabled={busy} title="Excluir bloco (preservar materiais e notas)" className="icon-button" onClick={()=>onClose(block,false)}><Trash2 size={17}/></button></div>
   </div>}
  </div>
  {canWrite&&block.id&&<div className="block-primary-actions">
   {pending.length>0&&<Button small variant="secondary" icon={Check} disabled={busy} onClick={()=>{if(window.confirm(`Confirmar solicitação no SAP de ${pending.length} material(is) do ${block.name}?`))onStatus(pending.map(m=>m.id),'solicitado')}}>Solicitar no SAP ({pending.length})</Button>}
   {ready.length>0&&<Button small icon={ReceiptText} disabled={busy} onClick={()=>onInvoice(block.id)}>Registrar NF deste bloco ({ready.length})</Button>}
   <Button small variant="secondary" icon={CheckCircle2} disabled={busy} onClick={()=>onClose(block,true)}>Encerrar bloco</Button>
  </div>}
  {canWrite&&rows.length>0&&<div className="block-operations">
   <label><input type="checkbox" aria-label={`Selecionar visíveis de ${block.name}`} checked={rows.every(m=>selected.includes(m.id))} onChange={e=>setSelected(prev=>e.target.checked?[...new Set([...prev,...rows.map(m=>m.id)])]:prev.filter(k=>!rows.some(m=>m.id===k)))}/> Selecionar visíveis</label>
   <div className="block-status-action"><Select aria-label={`Status dos itens visíveis de ${block.name}`} value={status} onChange={setStatus}><option value="solicitado">Pedido</option><option value="rascunho">A pedir</option><option value="concluido">Concluído</option><option value="cancelado">Cancelado</option></Select><Button variant="secondary" small disabled={busy} onClick={()=>onStatus(rows.map(m=>m.id),status)}>Aplicar aos visíveis</Button></div>
  </div>}
  <div className="block-items">{rows.map(m=><div className={`block-item block-item-${m.process==='3d'?'3d':m.process==='cnc'?'cnc':'other'}`} key={m.id}>
   {canWrite&&<input type="checkbox" aria-label={`Selecionar ${m.description||m.sap_code||m.forms_code}`} checked={selected.includes(m.id)} onChange={e=>setSelected(prev=>e.target.checked?[...new Set([...prev,m.id])]:prev.filter(k=>k!==m.id))}/>}
   <div className="block-item-main"><strong title={m.description}>{m.description||m.sap_code||m.forms_code}</strong><small>SAP {m.sap_code||'—'} · Forms {m.forms_code||'—'} · {m.site_name||'—'}</small><small>{dateLabel(m.requested_on)} · {money(itemTotal(m))}</small></div><ProcessTag process={m.process}/><Status value={m.status}/>{canWrite&&<button className="icon-button" title="Editar material" disabled={busy} onClick={()=>onEdit(m)}><Pencil size={15}/></button>}
  </div>)}{!rows.length&&<p className="block-empty-hint">{received?'Consulte os materiais em Notas recebidas abaixo.':members.length?'Nenhum material corresponde aos filtros.':'Mova materiais para este grupo.'}</p>}</div>
 </section>;
}
function MaterialTable({rows,selection=[],onSelect,onSelectAll,onEdit,onOpenInvoice,compact=false,showCheckbox=false,invoiceDates=false}){return <div className="table-wrap"><table><thead><tr>{showCheckbox&&<th className="col-check"><input type="checkbox" aria-label="Selecionar os itens visíveis" checked={rows.length>0&&rows.every(r=>selection.includes(r.id))} onChange={e=>onSelectAll(rows.map(x=>x.id),e.target.checked)}/></th>}<th>{invoiceDates?'Data NF / pedido':'Data'}</th><th>Site</th><th>Material</th><th>SAP / Forms</th><th>Processo</th><th>Qtd.</th><th>Valor total</th><th>Situação</th>{!compact&&<th>Nota</th>}{onEdit&&<th className="action-col">Ação</th>}</tr></thead><tbody>{rows.map(r=><tr key={r.id}>{showCheckbox&&<td><input type="checkbox" aria-label={`Selecionar ${r.description||r.sap_code||r.forms_code}`} checked={selection.includes(r.id)} onChange={e=>onSelect(r.id,e.target.checked)}/></td>}<td className="no-wrap muted">{dateLabel(invoiceDates?r.invoice_issued_on||r.requested_on:r.requested_on)}</td><td className="no-wrap">{r.site_name||'—'}</td><td><strong className="material-name" title={r.description||'Material sem descrição'}>{r.description||'Sem descrição'}</strong>{r.block_name&&<small className="subcell">{r.block_name}</small>}</td><td><div className="codes"><span>{r.sap_code||'—'}</span><span>{r.forms_code||'—'}</span></div></td><td><ProcessTag process={r.process}/></td><td className="num">{Number(r.quantity||0).toLocaleString('pt-BR')}</td><td className="num no-wrap strong">{money(itemTotal(r))}</td><td><Status value={r.status}/></td>{!compact&&<td>{r.invoice_number?<button className="text-link" onClick={()=>onOpenInvoice?.(r.invoice_id)}>{r.invoice_number}</button>:<span className="muted">—</span>}</td>}{onEdit&&<td><button title="Editar material" className="icon-button" onClick={()=>onEdit(r)}><Pencil size={16}/></button></td>}</tr>)}</tbody></table>{!rows.length&&<Empty title="Nenhum material nesta visualização" description="Experimente ajustar a busca ou cadastrar um material."/>}</div>}
function MaterialEditor({record,sites,blocks,onClose,onSave,onDelete,busy}){
 const [form,setForm]=useState(()=>({sap_code:'',forms_code:'',description:'',process:'indefinido',quantity:1,unit_price:0,site_id:sites[0]?.id||'',requested_on:today(),status:'rascunho',block_id:record?'':'auto',notes:'',...record}));
 const put=(key,value)=>setForm(p=>({...p,[key]:value}));
 const submit=async e=>{e.preventDefault();if(!form.sap_code?.trim()&&!form.forms_code?.trim())return alert('Informe SAP ou Forms.');if(!form.site_id)return alert('Cadastre um site antes de lançar.');if(!(Number(form.quantity)>0)||Number(form.unit_price)<0)return alert('Confira quantidade e valor.');await onSave(cleanMaterial({...form,quantity:Number(form.quantity),unit_price:Number(form.unit_price),block_id:form.block_id==='auto'?null:form.block_id||null,...(!record?{auto_group_on_insert:form.block_id==='auto'}:{}),...(record?.id?{id:record.id}:{})}));};
 return <Modal title={record?'Editar material':'Novo lançamento'} onClose={onClose} wide><form onSubmit={submit}><div className="form-grid"><Field label="Código SAP"><TextInput autoFocus value={form.sap_code} onChange={v=>put('sap_code',v)} placeholder="Ex.: 10083071"/></Field><Field label="Número do Forms"><TextInput value={form.forms_code} onChange={v=>put('forms_code',v)} placeholder="Ex.: 859"/></Field><div className="span-2"><Field label="Descrição do material"><TextInput value={form.description} onChange={v=>put('description',v)} placeholder="Nome ou descrição da peça"/></Field></div><Field label="Site"><Select required value={form.site_id} onChange={v=>put('site_id',v)}><Opts items={sites.map(s=>[s.id,s.name])} blank="Selecione o site"/></Select></Field><Field label="Data do pedido"><TextInput type="date" required value={form.requested_on} onChange={v=>put('requested_on',v)}/></Field><Field label="Processo"><Select value={form.process} onChange={v=>put('process',v)}>{PROCESSES.map(s=><option key={s} value={s}>{PROCESS_NAMES[s]}</option>)}</Select></Field><Field label="Situação"><Select value={form.status} onChange={v=>put('status',v)} disabled={Boolean(record?.invoice_id)}>{STATUSES.filter(s=>s!=='nota_recebida'||!!record?.invoice_id).map(s=><option key={s} value={s}>{STATUS_NAMES[s]}</option>)}</Select></Field><Field label="Quantidade"><TextInput type="number" min="0.001" step="0.001" required value={form.quantity} onChange={v=>put('quantity',v)}/></Field><Field label="Valor unitário (R$)"><TextInput type="number" min="0" step="0.01" required value={form.unit_price} onChange={v=>put('unit_price',v)}/></Field><Field label="Bloco" hint="Sem bloco mantém o material separado até você organizá-lo."><Select value={form.block_id||''} onChange={v=>put('block_id',v)}>{!record&&<option value="auto">Organizar automaticamente</option>}<Opts items={blocks.map(b=>[b.id,b.name])} blank="Sem bloco"/></Select></Field><Field label="Total calculado"><div className="read-only-value">{money(itemTotal(form))}</div></Field><div className="span-2"><Field label="Observações"><textarea rows="3" value={form.notes||''} onChange={e=>put('notes',e.target.value)} placeholder="Informações complementares"/></Field></div>{record?.invoice_id&&<div className="notice span-2"><Lock size={16}/> Material com nota fiscal vinculada. Desvincule a nota para alterar seu status.</div>}</div><div className="modal-actions">{record&&<Button variant="danger" icon={Trash2} disabled={busy||!!record.invoice_id} onClick={()=>onDelete(record)}>Excluir</Button>}<span className="grow"/><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button icon={Save} type="submit" disabled={busy}>Salvar material</Button></div></form></Modal>
}
function ImportEditor({sites,blocks,onClose,onSave,busy}){
 const [raw,setRaw]=useState('');const [site,setSite]=useState(sites[0]?.id||'');const [block,setBlock]=useState('auto');const [date,setDate]=useState(today());const [status,setStatus]=useState('rascunho');const [preview,setPreview]=useState(null);const [err,setErr]=useState('');
 const check=()=>{try{const parsed=parseExcel(raw);setPreview(parsed);setErr('')}catch(e){setErr(e.message);setPreview(null)}};
 return <Modal title="Importar materiais do Excel" onClose={onClose} wide><p className="muted">Cole as colunas nesta ordem: <strong>SAP, Forms, Descrição, Processo, Quantidade, Valor unitário</strong>. Uma linha por material; campos separados por tabulação.</p><div className="form-grid"><Field label="Site"><Select value={site} onChange={setSite}><Opts items={sites.map(s=>[s.id,s.name])} blank="Selecione o site"/></Select></Field><Field label="Data"><TextInput type="date" value={date} onChange={setDate}/></Field><Field label="Bloco"><Select value={block} onChange={setBlock}><option value="auto">Organizar automaticamente</option><Opts items={blocks.map(b=>[b.id,b.name])} blank="Sem bloco"/></Select></Field><Field label="Etapa inicial (A pedir → Pedido)"><Select value={status} onChange={setStatus}>{STATUSES.filter(s=>s!=='nota_recebida').map(s=><option key={s} value={s}>{STATUS_NAMES[s]}</option>)}</Select></Field></div><textarea className="paste-area" rows="9" value={raw} onChange={e=>{setRaw(e.target.value);setPreview(null)}} placeholder={'10083071\t859\tSuporte de sensor\t3d\t2\t45,90\n10122618\t862\tGabarito\tcnc\t1\t120,00'}/><div className="info-strip">{preview?<span><CheckCircle2 size={16}/> {preview.length} material(is) válido(s). Total: {money(preview.reduce((acc,m)=>acc+itemTotal(m),0))}</span>:<span><Info size={16}/> Copie diretamente as células da planilha, sem cabeçalho.</span>}{err&&<span className="error-text">{err}</span>}</div><div className="modal-actions"><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button variant="secondary" icon={Eye} onClick={check}>Conferir dados</Button><Button icon={Upload} disabled={busy||!site||!preview?.length} onClick={()=>onSave(preview.map((r,i)=>({...r,site_id:site,block_id:block==='auto'?null:block||null,auto_group_on_insert:block==='auto',requested_on:date,status,position:i,notes:''})))}>Importar {preview?.length||''} materiais</Button></div></Modal>
}
function InvoiceEditor({invoice,materials,blocks,startBlockId='',onClose,onSave,busy}){
 const [form,setForm]=useState({number:invoice?.number||'',access_key:invoice?.access_key||'',issued_on:invoice?.issued_on||today(),notes:invoice?.notes||''});
 const allowed=m=>!m.invoice_id||m.invoice_id===invoice?.id;
 const canInvoice=m=>allowed(m)&&(m.status==='solicitado'||m.invoice_id===invoice?.id);
 const blockList=blocks.map(block=>({block,items:materials.filter(m=>m.block_id===block.id)}));
 const [chosenBlock,setChosenBlock]=useState(startBlockId||'');
 const suggested=materials.filter(m=>m.block_id===startBlockId&&canInvoice(m)).slice(0,4).map(m=>m.id);
 const [selected,setSelected]=useState(invoice?.material_ids||suggested);
 const [search,setSearch]=useState('');const [site,setSite]=useState('');const [process,setProcess]=useState('');const [order,setOrder]=useState('sap');
 const chooseBlock=blockId=>{
   setChosenBlock(blockId);
   if(!blockId){setSelected([]);return;}
   const items=materials.filter(m=>m.block_id===blockId&&canInvoice(m)).slice(0,4);
   setSelected(items.map(m=>m.id));
 };
 const targetBlock=blockList.find(b=>b.block.id===chosenBlock);
 const targetTotal=targetBlock?.items?.length||0;
 const targetReady=targetBlock?.items?.filter(canInvoice).length||0;
 const available=sortMaterials(materials.filter(canInvoice).filter(m=>(!chosenBlock||m.block_id===chosenBlock)&&(!search||[m.sap_code,m.forms_code,m.description,m.site_name].some(x=>String(x||'').toLowerCase().includes(search.toLowerCase())))&&(!site||m.site_id===site)&&(!process||m.process===process)),order);
 const siteOptions=[...new Map(materials.map(x=>[x.site_id,x.site_name])).entries()].filter(x=>x[0]);
 const toggle=materialId=>setSelected(prev=>prev.includes(materialId)?prev.filter(x=>x!==materialId):prev.length<4?[...prev,materialId]:prev);
 const selectedItems=materials.filter(m=>selected.includes(m.id));
 const submit=async e=>{e.preventDefault();if(!selected.length)return alert('Selecione de 1 a 4 materiais.');if(form.access_key&&!/^\d{44}$/.test(form.access_key))return alert('A chave deve conter 44 dígitos ou ficar vazia.');await onSave({id:invoice?.id||null,...form},selected);};
 return <Modal title={invoice?'Editar nota fiscal':'Registrar nota fiscal'} onClose={onClose} wide><form onSubmit={submit}>
  <div className="workflow-hint"><ReceiptText size={20}/><div><strong>Etapa 3 — Nota recebida</strong><span>Primeiro solicite os materiais no SAP (status Pedido). Quando a NF chegar, selecione o bloco e informe número e chave. Só os materiais vinculados serão atualizados.</span></div></div>
  <div className="form-grid">
   <div className="span-2"><Field label="Carregar materiais de um bloco (até 4)"><Select value={chosenBlock} onChange={chooseBlock}><Opts blank="Escolher bloco ou selecionar manualmente" items={blockList.map(({block,items})=>[block.id,`${block.name} · ${[...new Set(items.map(m=>PROCESS_NAMES[m.process]))].join(' / ')||'Vazio'} · ${items.length}/4 · ${items.filter(canInvoice).length} disponível(is)`])}/></Select></Field></div>
   {chosenBlock&&<div className="span-2"><div className="block-ready-hint">{targetReady} de {targetTotal} material(is) deste bloco podem receber NF. {targetReady<targetTotal?'Os materiais em A pedir devem passar para Pedido antes de registrar a nota.':''}</div></div>}
   <Field label="Número da nota"><TextInput autoFocus required placeholder="Ex.: 123456" value={form.number} onChange={v=>setForm(p=>({...p,number:v}))}/></Field>
   <Field label="Data de emissão"><TextInput type="date" required value={form.issued_on} onChange={v=>setForm(p=>({...p,issued_on:v}))}/></Field>
   <div className="span-2"><Field label="Chave NF-e (44 dígitos, opcional)"><TextInput
    value={form.access_key}
    inputMode="numeric"
    onChange={v=>setForm(p=>({...p,access_key:v.replace(/\D/g,'').slice(0,44)}))}
    placeholder="Cole a chave com ou sem espaços"
   /></Field></div>
  </div>
  <div className="subhead compact"><div><h2>Materiais desta nota</h2><p>Selecione até quatro materiais já solicitados no SAP.</p></div><span className={`count-badge ${selected.length===4?'full':''}`}>{selected.length} / 4</span></div>
  <div className="invoice-select-filters"><div className="search-field"><Search size={16}/><TextInput value={search} onChange={setSearch} placeholder="SAP / Forms / descrição"/></div><Select value={site} onChange={setSite}><Opts items={siteOptions} blank="Todos os sites"/></Select><Select value={process} onChange={setProcess}><Opts items={PROCESSES.map(x=>[x,PROCESS_NAMES[x]])} blank="Todos os processos"/></Select><Select value={order} onChange={setOrder}>{SORTS.map(([k,v])=><option key={k} value={k}>{v}</option>)}</Select></div>
  <div className="invoice-picker">{available.length?available.map(m=><label key={m.id} className={`invoice-choice ${selected.includes(m.id)?'chosen':''}`}><input type="checkbox" checked={selected.includes(m.id)} disabled={!selected.includes(m.id)&&selected.length>=4} onChange={()=>toggle(m.id)}/><span className="choice-content"><strong>{m.description||m.sap_code||m.forms_code}</strong><small>SAP {m.sap_code||'—'} · Forms {m.forms_code||'—'} · {m.site_name||'—'}</small><ProcessTag process={m.process}/></span><span className="num">{money(itemTotal(m))}</span></label>):<div className="picker-empty">Nenhum material em Pedido disponível. Solicite o bloco no SAP primeiro, ou altere os filtros.</div>}</div>
  <div className="invoice-total"><span>Total dos materiais selecionados</span><strong>{money(selectedItems.reduce((sum,m)=>sum+itemTotal(m),0))}</strong></div>
  <Field label="Observações"><textarea rows="2" value={form.notes} onChange={e=>setForm(p=>({...p,notes:e.target.value}))}/></Field>
  <div className="modal-actions"><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" icon={Save} disabled={busy||!selected.length}>Salvar NF e marcar Nota recebida</Button></div>
 </form></Modal>;
}
function Login({error,onLogin,busy}){const [email,setEmail]=useState('');const [password,setPassword]=useState('');return <div className="login-page"><div className="login-box"><div className="brand-mark login-mark"><FileSpreadsheet size={28}/></div><div className="login-head"><span className="eyebrow">CENTRAL DE OPERAÇÕES</span><h1>Bem-vindo ao NotaFlow</h1><p>Entre com sua conta autorizada para acessar os registros SAP.</p></div><form onSubmit={e=>{e.preventDefault();onLogin(email,password)}}><Field label="E-mail corporativo"><TextInput type="email" autoComplete="username" required value={email} onChange={setEmail} placeholder="seu@email.com"/></Field><Field label="Senha"><TextInput type="password" autoComplete="current-password" required value={password} onChange={setPassword} placeholder="••••••••"/></Field>{error&&<div className="inline-error"><AlertCircle size={16}/>{error}</div>}<Button type="submit" disabled={busy} className="login-submit">{busy?'Entrando...':'Acessar plataforma'}</Button></form><div className="login-foot"><ShieldCheck size={15}/> Acesso protegido por Supabase Authentication</div></div></div>}


const activityPretty=text=>String(text||'').replace(/\b(rascunho|solicitado|nota_recebida|concluido|cancelado)\b/g,code=>({rascunho:'A pedir',solicitado:'Pedido',nota_recebida:'Nota recebida',concluido:'Concluído',cancelado:'Cancelado'}[code]||code));
const STORAGE_REFERENCE_BYTES=500*1024*1024; // Referência do plano Free; pode mudar no Supabase.
function StoragePanel({usage,onRefresh}){
 const isValid=usage.bytes!==null&&Number.isFinite(usage.bytes);
 const used=isValid?usage.bytes:0;
 const ratio=isValid?used/STORAGE_REFERENCE_BYTES:0;
 const percent=Math.max(0,Math.min(100,ratio*100));
 const displayMb=bytes=>`${(bytes/(1024*1024)).toLocaleString('pt-BR',{maximumFractionDigits:1,minimumFractionDigits:1})} MB`;
 const state=ratio>=.95?'critical':ratio>=.8?'warning':'normal';
 return <section className="panel storage-panel" aria-label="Armazenamento do banco">
   <div className="storage-head"><div className="storage-title"><span className="storage-icon"><Database size={20}/></span><div><h2>Armazenamento do Supabase</h2><p>Tamanho real do PostgreSQL, incluindo índices e estruturas internas</p></div></div><Button variant="secondary" small icon={RefreshCw} onClick={onRefresh} disabled={usage.loading}>{usage.loading?'Consultando...':'Atualizar'}</Button></div>
   {isValid?<><div className="storage-values"><div><small>Utilizado</small><strong>{displayMb(used)}</strong></div><div><small>Restante (estimado)</small><strong>{displayMb(Math.max(0,STORAGE_REFERENCE_BYTES-used))}</strong></div><div><small>Referência do Free</small><strong>500 MB</strong></div></div>
     <div className="storage-progress" role="progressbar" aria-label="Percentual utilizado do limite de referência" aria-valuenow={Number((ratio*100).toFixed(2))} aria-valuemin={0} aria-valuemax={100}><span className={`storage-fill storage-${state}`} style={{width:`${percent}%`}}/></div>
     <div className="storage-foot"><span>{(ratio*100).toLocaleString('pt-BR',{maximumFractionDigits:2})}% da referência utilizada</span><span>{usage.checkedAt?`Atualizado em ${new Date(usage.checkedAt).toLocaleString('pt-BR')}`:''}</span></div>
     {ratio>=.8&&<div className={`storage-alert storage-${state}`}>{ratio>=.95?'Atenção: o espaço está próximo do limite de referência.':'O banco ultrapassou 80% do limite de referência.'}</div>}
   </>:<p className="storage-placeholder">{usage.loading?'Consultando o Supabase...':'Clique em Atualizar para consultar o espaço em uso.'}</p>}
   {usage.error&&<div className="storage-error"><AlertCircle size={16}/><span>{usage.error} Execute primeiro a atualização SQL desta versão.</span></div>}
   <p className="storage-disclaimer">Os 500 MB são uma referência para o plano Free, não uma consulta da sua franquia contratada. O tamanho pode incluir dados do próprio PostgreSQL. O painel não guarda medições históricas.</p>
 </section>;
}

export default function App(){
 const [page,setPage]=useState('dashboard');const [sidebar,setSidebar]=useState(false);const [db,setDb]=useState({sites:[],blocks:[],materials:[],invoices:[],invoice_materials:[],activity:[]});
 const [session,setSession]=useState(null);const [authReady,setAuthReady]=useState(!cloud);const [role,setRole]=useState('admin');const [loginError,setLoginError]=useState('');const [busy,setBusy]=useState(false);const [loading,setLoading]=useState(true);
 const [toast,setToast]=useState(null);const [modal,setModal]=useState(null);const [filter,setFilter]=useState({...EMPTY_FILTERS});const [sort,setSort]=useState('recent');const [pageno,setPageno]=useState(1);const [selected,setSelected]=useState([]);const [blockSelected,setBlockSelected]=useState([]);const [targetBlock,setTargetBlock]=useState('');const [blockStatus,setBlockStatus]=useState('solicitado');const [blockSearch,setBlockSearch]=useState('');const [invoiceSearch,setInvoiceSearch]=useState('');const [formsBatch,setFormsBatch]=useState('');const [blockFilters,setBlockFilters]=useState({...EMPTY_FILTERS});const [blockSort,setBlockSort]=useState('sap');const [invoiceFilters,setInvoiceFilters]=useState({...EMPTY_FILTERS});const [invoiceSort,setInvoiceSort]=useState('recent');const [activitySearch,setActivitySearch]=useState('');const [activityKind,setActivityKind]=useState('');const [activitySort,setActivitySort]=useState('recent');const [siteSearch,setSiteSearch]=useState('');const [dashboardSearch,setDashboardSearch]=useState('');const [dashboardSort,setDashboardSort]=useState('recent');
 const [dbUsage,setDbUsage]=useState({bytes:null,loading:false,error:'',checkedAt:null});
 const [activityShown,setActivityShown]=useState(20);
 const canWrite=!cloud||role==='admin';
 const refreshDbUsage=async()=>{
   if(!cloud||!canWrite)return;
   setDbUsage(prev=>({...prev,loading:true,error:''}));
   try{const bytes=await getDatabaseUsageBytes();setDbUsage({bytes,loading:false,error:'',checkedAt:new Date().toISOString()});}
   catch(e){setDbUsage(prev=>({...prev,loading:false,error:e.message||'Falha ao consultar armazenamento.'}));}
 };
 useEffect(()=>{if(page==='settings'&&cloud&&canWrite&&session?.user?.id)refreshDbUsage();},[page,cloud,canWrite,session?.user?.id]);
 useEffect(()=>{setActivityShown(20);},[activitySearch,activityKind,activitySort]);

 const shown=useMemo(()=>mergeView(db),[db]);
 const activityRows=useMemo(()=>{
   const materialById=new Map(shown.materials.map(m=>[m.id,m]));
   return [...shown.activity].map(a=>{
     const material=materialById.get(a.entity_id);
     let displaySummary=a.summary||'Registro atualizado';
     // Contexto para eventos antigos: sem criar nem gravar novos registros no banco.
     if(material&&['materials','nf_materials'].includes(a.entity)&&!displaySummary.includes('Forms')){
       displaySummary+=material.forms_code?` · Forms ${material.forms_code}`:'';
     }
     return {...a,displaySummary};
   }).filter(a=>(!activityKind||a.action===activityKind)&&(!activitySearch||[a.entity,a.action,a.displaySummary].some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(activitySearch.toLocaleLowerCase('pt-BR')))))
     .sort((a,b)=>activitySort==='oldest'?String(a.happened_at).localeCompare(String(b.happened_at)):String(b.happened_at).localeCompare(String(a.happened_at)));
 },[shown.activity,shown.materials,activityKind,activitySearch,activitySort]);

 const orderedBlocks=useMemo(()=>[...shown.blocks].sort((a,b)=>(a.position||0)-(b.position||0)||String(a.created_at).localeCompare(String(b.created_at))),[shown.blocks]);
 const filtered=useMemo(()=>sortMaterials(shown.materials.filter(x=>matches(x,filter,shown.sites)),sort),[shown.materials,shown.sites,filter,sort]);
 const pageSize=25;const pages=Math.max(1,Math.ceil(filtered.length/pageSize));const current=Math.min(pageno,pages);const rows=filtered.slice((current-1)*pageSize,current*pageSize);
 useEffect(()=>setPageno(1),[filter,sort]);
 const notify=(message,error=false)=>{setToast({message,error,at:Date.now()});};
 const refresh=async()=>{setLoading(true);try{setDb(await loadAll())}catch(e){notify(e.message,true)}finally{setLoading(false)}};
 useEffect(()=>{if(!cloud){refresh();return;}let active=true;
  supabase.auth.getSession().then(({data,error})=>{if(!active)return;if(error)setLoginError(error.message);setSession(data?.session||null);setAuthReady(true);});
  const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,next)=>{if(active){setSession(next);setAuthReady(true);}});
  return()=>{active=false;subscription.unsubscribe()};
 },[]);
 useEffect(()=>{if(!authReady)return;if(cloud&&!session){setLoading(false);return;}let active=true;(async()=>{try{if(cloud){const r=await getRole(session.user.id);if(active)setRole(r);}if(active)await refresh();}catch(e){if(active)notify(e.message,true)}})();return()=>{active=false}},[authReady,session?.user?.id]);
 const run=async(fn,success='Salvo com sucesso')=>{setBusy(true);try{await fn();await refresh();setModal(null);setSelected([]);setBlockSelected([]);notify(success);return true;}catch(e){notify(e.message,true);return false;}finally{setBusy(false)}};
 const selectPage=next=>{setPage(next);setSidebar(false);setSelected([]);setBlockSelected([]);setPageno(1)};
 const removeConfirm=(table,row,label)=>{if(!window.confirm(`Excluir ${label}? Esta ação não pode ser desfeita.`))return;run(()=>deleteRow(table,row.id),'Excluído com sucesso')};
 const toggleSelect=(materialId,enabled)=>setSelected(prev=>enabled?[...new Set([...prev,materialId])]:prev.filter(x=>x!==materialId));
 const toggleSelectAll=(ids,enabled)=>setSelected(prev=>enabled?[...new Set([...prev,...ids])]:prev.filter(x=>!ids.includes(x)));
 const materialModal=(record=null)=>setModal({kind:'material',record});
 const invoiceModal=(record=null,blockId='')=>setModal({kind:'invoice',record,blockId});
 const counts={materials:shown.materials.length,open:shown.materials.filter(m=>['rascunho','solicitado'].includes(m.status)).length,notes:shown.invoices.length,amount:shown.materials.reduce((t,m)=>t+itemTotal(m),0)};
 const latest=sortMaterials(shown.materials.filter(m=>!dashboardSearch||[m.sap_code,m.forms_code,m.description,m.site_name,PROCESS_NAMES[m.process]].some(v=>String(v||'').toLowerCase().includes(dashboardSearch.toLowerCase()))),dashboardSort).slice(0,8);
 // Exclusão em massa por ID do material. Não afeta outros materiais do mesmo bloco.
 const deleteSelectedMaterials=async()=>{
   if(!canWrite||busy||!selected.length)return;
   const ids=[...new Set(selected)];
   const targets=shown.materials.filter(material=>ids.includes(material.id));
   if(targets.length!==ids.length){notify('A seleção mudou. Atualize os dados e selecione novamente.',true);return;}
   const linkedIds=new Set(shown.invoice_materials.map(link=>link.material_id));
   const linked=targets.filter(material=>material.invoice_id||linkedIds.has(material.id));
   if(linked.length){
     notify(`${linked.length} material(is) vinculado(s) a nota fiscal. Desvincule a nota antes de excluir. Nenhum material foi excluído.`,true);
     return;
   }
   const question=`Excluir definitivamente ${ids.length} material(is) selecionado(s) do banco de dados?\n\nOs materiais serão removidos dos blocos, mas os outros materiais e os blocos continuarão. O histórico resumido de exclusão será mantido.\n\nEsta ação não pode ser desfeita.`;
   if(!window.confirm(question))return;
   setBusy(true);
   try{
     if(cloud){
       // Um DELETE transacional para a seleção inteira; RLS e FKs continuam sendo aplicadas.
       const {data,error}=await supabase.from('nf_materials').delete().in('id',ids).select('id');
       if(error)throw error;
       if((data||[]).length!==ids.length)throw new Error(`Exclusão incompleta: ${(data||[]).length} de ${ids.length} material(is) removido(s). Confira as permissões e atualize.`);
     }else{
       // Mesmo comportamento da exclusão individual no modo demonstração.
       for(const materialId of ids)await deleteRow('materials',materialId);
     }
     setSelected([]);
     notify(`${ids.length} material(is) excluído(s) do banco com sucesso.`);
   }catch(error){
     notify(error.message||'Não foi possível excluir os materiais selecionados.',true);
   }finally{
     await refresh();
     setBusy(false);
   }
 };
 const onStatus=()=>{if(!selected.length)return;run(()=>setMaterialStatus(selected,blockStatus),'Status atualizado para os materiais selecionados')};
 const filterRows=(source)=>sortMaterials(source.filter(m=>matches(m,blockFilters,shown.sites)).filter(m=>!blockSearch||[m.description,m.sap_code,m.forms_code,PROCESS_NAMES[m.process],m.site_name].some(v=>String(v||'').toLowerCase().includes(blockSearch.toLowerCase()))),blockSort);
 const blockEntries=orderedBlocks.map(block=>{const members=shown.materials.filter(m=>m.block_id===block.id);return {block,members,stage:blockStage(members)};});
 const hasBlockFilters=Object.values(blockFilters).some(Boolean)||Boolean(blockSearch);
 const visibleBlocks=stage=>blockEntries.filter(entry=>entry.stage===stage&&(!hasBlockFilters||filterRows(entry.members).length));
 const closeBlockConfirm=(block,ending=true)=>{
   const verb=ending?'Encerrar':'Excluir';
   if(window.confirm(`${verb} o bloco “${block.name}”?\n\nSomente o agrupamento será removido. Os materiais, status, SAP, Forms, notas fiscais, vínculos e histórico serão preservados. Os materiais ficarão sem bloco até uma nova organização manual.`))run(()=>closeBlock(block.id),`Bloco ${ending?'encerrado':'excluído'}; materiais e notas preservados`);
 };
 const shiftBlock=(block,direction)=>{
   const stage=blockEntries.find(entry=>entry.block.id===block.id)?.stage;
   const peers=blockEntries.filter(entry=>entry.stage===stage).map(entry=>entry.block.id);
   const neighbor=peers[peers.indexOf(block.id)+direction];if(!neighbor)return;
   const ids=orderedBlocks.map(b=>b.id);const first=ids.indexOf(block.id),second=ids.indexOf(neighbor);
   [ids[first],ids[second]]=[ids[second],ids[first]];
   run(()=>reorderBlocks(ids),'Ordem dos blocos salva');
 };
 const renderBlock=entry=>{
   const peers=blockEntries.filter(other=>other.stage===entry.stage);
   const index=peers.findIndex(other=>other.block.id===entry.block.id);
   return <BlockPanel key={entry.block.id} block={entry.block} members={entry.members} rows={filterRows(entry.members.filter(m=>!isReceivedMaterial(m)))} selected={blockSelected} setSelected={setBlockSelected} canWrite={canWrite} busy={busy} onEdit={materialModal} onRename={block=>setModal({kind:'block',record:block})} onClose={closeBlockConfirm} onShift={shiftBlock} canMoveUp={index>0} canMoveDown={index<peers.length-1} onStatus={(ids,status)=>run(()=>setMaterialStatus(ids,status),'Status dos materiais atualizado')} onInvoice={blockId=>invoiceModal(null,blockId)}/>;
 };
 const initial=!authReady||(loading&&(!cloud||session));
 if(initial)return <div className="loading-screen"><div className="brand-mark"><FileSpreadsheet/></div><strong>NotaFlow</strong><span>Carregando seu ambiente...</span></div>;
 if(cloud&&!session)return <Login error={loginError} busy={busy} onLogin={async(email,password)=>{setBusy(true);setLoginError('');try{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;}catch(e){setLoginError(e.message)}finally{setBusy(false)}}}/>;
 return <div className="shell">
  <aside className={`sidebar ${sidebar?'sidebar-open':''}`}><div className="brand"><div className="brand-mark"><FileSpreadsheet size={23}/></div><div><strong>NotaFlow</strong><span>OPERATIONS HUB</span></div><button className="sidebar-close icon-button" onClick={()=>setSidebar(false)}><X size={19}/></button></div><div className="nav-label">ESPAÇO DE TRABALHO</div><nav>{menu.map(({id,name,icon:Icon})=><button key={id} className={`nav-item ${page===id?'active':''}`} onClick={()=>selectPage(id)}><Icon size={19}/><span>{name}</span>{page===id&&<span className="nav-active"/>}</button>)}</nav><div className="sidebar-bottom"><div className="status-cloud"><span className="cloud-dot"/>{cloud?'Supabase conectado':'Modo demonstração'}</div><div className="sidebar-user"><div className="avatar">{cloud?session.user.email?.[0]?.toUpperCase():'D'}</div><div><strong>{cloud?session.user.email?.split('@')[0]:'Demonstração'}</strong><small>{canWrite?'Administrador':'Visualizador'}</small></div>{cloud&&<button className="icon-button" title="Sair" onClick={()=>supabase.auth.signOut()}><LogOut size={17}/></button>}</div></div></aside>
  {sidebar&&<button className="mobile-backdrop" onClick={()=>setSidebar(false)} aria-label="Fechar navegação"/>}
  <div className="main-column"><header className="topbar"><div className="top-left"><button className="mobile-menu icon-button" onClick={()=>setSidebar(true)} aria-label="Abrir menu"><Menu size={22}/></button><div className="breadcrumb"><span>NotaFlow</span><ChevronRight size={14}/><strong>{menu.find(x=>x.id===page)?.name}</strong></div></div><div className="top-actions"><span className="top-date"><CalendarDays size={15}/>{dateLabel(today())}</span><span className="permission-label"><ShieldCheck size={15}/>{canWrite?'Admin':'Leitura'}</span><button title="Atualizar dados" className="icon-button" onClick={refresh}><RefreshCw size={18}/></button></div></header>
  <main className="content">
   {page==='dashboard'&&<><Heading eyebrow="PAINEL DE CONTROLE" title="Visão geral" description="Acompanhe pedidos, materiais e notas fiscais em um único lugar." actions={canWrite&&<Button icon={Plus} onClick={()=>materialModal()}>Novo lançamento</Button>}/><div className="stats-grid"><Stat icon={Boxes} label="Materiais cadastrados" value={counts.materials} detail="Todos os registros"/><Stat icon={RefreshCw} label="Em andamento" value={counts.open} detail="Rascunho e pedido"/><Stat icon={ReceiptText} label="Notas registradas" value={counts.notes} detail="Documentos fiscais"/><Stat icon={Wallet} label="Valor dos materiais" value={money(counts.amount)} detail="Quantidade × valor unitário" accent/></div><div className="dashboard-grid"><section className="panel"><Subhead title="Últimos lançamentos" description="Registros mais recentes. Consulte e edite na planilha." actions={<Button variant="secondary" small icon={ArrowRight} onClick={()=>selectPage('records')}>Ver todos</Button>}/><div className="dashboard-inline-filters"><div className="search-field"><Search size={15}/><TextInput value={dashboardSearch} onChange={setDashboardSearch} placeholder="Buscar SAP, Forms, material"/></div><Select value={dashboardSort} onChange={setDashboardSort}>{SORTS.map(([k,v])=><option key={k} value={k}>{v}</option>)}</Select></div><MaterialTable rows={latest} compact onEdit={canWrite?materialModal:null}/>{!latest.length&&canWrite&&<div className="table-footer"><Button small icon={Plus} onClick={()=>materialModal()}>Criar lançamento</Button></div>}</section><section className="panel quick-panel"><Subhead title="Acesso rápido" description="Atalhos para as atividades do dia."/><div className="quick-list">{[{name:'Lançamentos',desc:'Filtrar e atualizar materiais',icon:Table2,to:'records'},{name:'Blocos',desc:'Organizar por grupos e processos',icon:Layers3,to:'blocks'},{name:'Notas fiscais',desc:'Vincular até quatro materiais',icon:ReceiptText,to:'invoices'},{name:'Consulta SAP / Forms',desc:'Localizar códigos rapidamente',icon:Search,to:'lookup'}].map(({name,desc,icon:Icon,to})=><button key={to} onClick={()=>selectPage(to)} className="quick-item"><span className="quick-icon"><Icon size={19}/></span><span><strong>{name}</strong><small>{desc}</small></span><ArrowRight size={17}/></button>)}</div></section></div></>}
   {page==='records'&&<><Heading eyebrow="GESTÃO DE MATERIAIS" title="Lançamentos" description="Planilha de materiais com buscas, filtros, ordenação e atualização individual de status." actions={canWrite&&<><Button variant="secondary" icon={Upload} onClick={()=>setModal({kind:'import'})}>Colar do Excel</Button><Button icon={Plus} onClick={()=>materialModal()}>Novo material</Button></>}/><section className="panel"><Subhead title="Planilha de lançamentos" description={`${filtered.length} material(is) encontrado(s)`} actions={<><ExcelExport filters={filter} sort={sort}/><ExportButton rows={filtered}/><div className="sort-control"><ArrowUpDown size={15}/><Select aria-label="Ordenar" value={sort} onChange={setSort}>{SORTS.map(([k,v])=><option key={k} value={k}>{v}</option>)}</Select></div></>}/><Filters value={filter} set={setFilter} sites={shown.sites} invoice/><div className="date-filters"><label>De <TextInput type="date" value={filter.from} onChange={v=>setFilter(p=>({...p,from:v}))}/></label><label>Até <TextInput type="date" value={filter.to} onChange={v=>setFilter(p=>({...p,to:v}))}/></label></div>{canWrite&&selected.length>0&&<div className="bulk-bar"><strong>{selected.length} selecionado(s)</strong><Select value={blockStatus} onChange={setBlockStatus}>{STATUSES.filter(s=>s!=='nota_recebida').map(s=><option key={s} value={s}>{STATUS_NAMES[s]}</option>)}</Select><Button small icon={Check} disabled={busy} onClick={onStatus}>Alterar status</Button><Button small variant="secondary" disabled={busy} onClick={()=>setSelected([])}>Desmarcar</Button><Button small variant="danger" icon={Trash2} disabled={busy} onClick={deleteSelectedMaterials}>Excluir selecionados</Button></div>}<MaterialTable rows={rows} selection={selected} showCheckbox={canWrite} onSelect={toggleSelect} onSelectAll={toggleSelectAll} onEdit={canWrite?materialModal:null} onOpenInvoice={r=>invoiceModal(shown.invoices.find(x=>x.id===r))}/><Pagination current={current} pages={pages} total={filtered.length} onPage={setPageno}/></section></>}
   {page==='blocks'&&<>
    <Heading eyebrow="ORGANIZAÇÃO DE MATERIAIS" title="Blocos de trabalho" description="Grupos temporários de até quatro materiais. Novos cadastros são organizados por site e processo; você pode misturar CNC e 3D manualmente." actions={canWrite&&<><Button variant="secondary" icon={Layers3} disabled={busy} onClick={()=>run(autoGroupMaterials,'Materiais elegíveis sem bloco organizados; notas preservadas')}>Organizar sem bloco</Button><Button icon={Plus} disabled={busy} onClick={()=>setModal({kind:'block'})}>Criar bloco</Button></>}/>
    <div className="workflow-steps"><span>1 · <b>A pedir</b> — aguardando solicitação</span><ChevronRight size={15}/><span>2 · <b>Pedido</b> — solicitado no SAP</span><ChevronRight size={15}/><span>3 · <b>Nota recebida</b> — registrar NF e encerrar bloco</span></div>
    <section className="panel block-toolbar enhanced-block-toolbar">
     <div className="block-filters-full"><Filters value={blockFilters} set={setBlockFilters} sites={shown.sites} invoice showSort sort={blockSort} setSort={setBlockSort}/></div>
     {canWrite&&<div className="block-move-bar"><strong>{blockSelected.length} selecionado(s)</strong><Select aria-label="Bloco de destino" value={targetBlock} onChange={setTargetBlock}><Opts items={orderedBlocks.map(b=>{const members=shown.materials.filter(m=>m.block_id===b.id);const types=[...new Set(members.map(m=>PROCESS_NAMES[m.process]||'Não definido'))];return [b.id,`${b.name} · ${types.length>1?'Misto · ':''}${types.join(' / ')||'Vazio'} · ${members.length}/4`];})} blank="Mover para Sem bloco"/></Select><Button variant="secondary" small icon={MoveRight} disabled={busy||!blockSelected.length} onClick={()=>run(()=>moveMaterials(blockSelected,targetBlock),'Materiais movidos')}>Mover selecionados</Button><Button variant="secondary" small disabled={!blockSelected.length||busy} onClick={()=>setBlockSelected([])}>Desmarcar</Button></div>}
    </section>
    <section className="blocks-section" aria-label="Blocos ativos aguardando solicitação">
     <Subhead title="Blocos ativos — aguardando solicitação" description="Prepare os grupos e solicite os materiais no SAP. A ordem e os nomes são salvos."/>
     <div className="blocks-grid">{visibleBlocks('pending').map(renderBlock)}</div>
     {!visibleBlocks('pending').length&&<p className="section-empty">Nenhum bloco aguardando solicitação nesta visualização.</p>}
    </section>
    <section className="blocks-section" aria-label="Blocos já solicitados no SAP">
     <Subhead title="Pedidos no SAP" description="Grupos com materiais em Pedido, aguardando o registro da nota fiscal."/>
     <div className="blocks-grid">{visibleBlocks('requested').map(renderBlock)}</div>
     {!visibleBlocks('requested').length&&<p className="section-empty">Nenhum bloco com pedido no SAP nesta visualização.</p>}
    </section>
    <section className="blocks-section" aria-label="Materiais temporariamente sem bloco">
     <Subhead title="Temporariamente sem bloco" description="Materiais retirados manualmente permanecem aqui. Organize quando quiser; cadastros novos não os movimentam."/>
     <BlockPanel block={{id:null,name:'Sem bloco'}} members={shown.materials.filter(m=>!m.block_id&&!isReceivedMaterial(m))} rows={filterRows(shown.materials.filter(m=>!m.block_id&&!isReceivedMaterial(m)))} selected={blockSelected} setSelected={setBlockSelected} canWrite={canWrite} busy={busy} onEdit={materialModal} onStatus={(ids,status)=>run(()=>setMaterialStatus(ids,status),'Status dos materiais atualizado')}/>
    </section>
    <section className="blocks-section" aria-label="Notas recebidas">
     <Subhead title="Notas recebidas" description="Consulta dos materiais com NF ou concluídos. Esta lista não cria blocos e mantém os vínculos fiscais por material."/>
     {visibleBlocks('received').length>0&&<><p className="received-block-hint">Estes agrupamentos já podem ser encerrados:</p><div className="blocks-grid received-blocks">{visibleBlocks('received').map(renderBlock)}</div></>}
     <div className="panel received-materials"><MaterialTable rows={filterRows(shown.materials.filter(isReceivedMaterial))} invoiceDates onEdit={canWrite?materialModal:null} onOpenInvoice={invoiceId=>canWrite?invoiceModal(shown.invoices.find(invoice=>invoice.id===invoiceId)):selectPage('invoices')}/></div>
    </section>
   </>}
   {page==='invoices'&&<>
     <Heading eyebrow="DOCUMENTOS FISCAIS" title="Notas fiscais" description="Após solicitar no SAP, escolha o bloco, informe número e chave da nota e vincule até quatro materiais." actions={canWrite&&<Button icon={Plus} onClick={()=>invoiceModal()}>Registrar NF</Button>}/>
     <section className="panel invoice-ready-panel"><Subhead title="Blocos aguardando nota" description="Você pode chamar os materiais já solicitados de um bloco diretamente aqui."/>
       <div className="invoice-block-grid">{orderedBlocks.map(block=>{const members=shown.materials.filter(m=>m.block_id===block.id);const pending=members.filter(m=>m.status==='solicitado'&&!m.invoice_id);if(!pending.length)return null;return <div className={`invoice-block-pick ${members.some(m=>m.process==='cnc')?'type-cnc':'type-3d'}`} key={block.id}><strong>{block.name}</strong><span className="muted">{pending.length} aguardando nota · {money(pending.reduce((s,m)=>s+itemTotal(m),0))}</span><div className="block-processes">{[...new Set(pending.map(m=>m.process))].map(p=><ProcessTag process={p} key={p}/>)}</div>{canWrite&&<Button small icon={ReceiptText} onClick={()=>invoiceModal(null,block.id)}>Chamar bloco para NF</Button>}</div>})}</div>
       {!shown.materials.some(m=>m.status==='solicitado'&&!m.invoice_id)&&<p className="muted">Nenhum material aguardando NF. Vá a Blocos e clique em “Solicitar no SAP”.</p>}
     </section>
     <section className="panel"><Subhead title="Notas cadastradas" description={`${shown.invoices.length} nota(s) cadastrada(s)`} actions={<ExcelExport filters={{...invoiceFilters,invoice:'with'}} invoiceSearch={invoiceSearch}/>}/>
       <Filters value={invoiceFilters} set={setInvoiceFilters} sites={shown.sites} showSort={false}/>
       <div className="invoice-select-filters invoice-list-options"><div className="search-field"><Search size={17}/><TextInput value={invoiceSearch} onChange={setInvoiceSearch} placeholder="Número, chave, SAP ou Forms da NF"/></div><label>Ordenar notas <Select value={invoiceSort} onChange={setInvoiceSort}><option value="recent">Mais recentes</option><option value="oldest">Mais antigas</option><option value="number">Número da nota</option><option value="value_desc">Maior valor total</option><option value="value_asc">Menor valor total</option><option value="date_desc">Data da NF (recente)</option><option value="date_asc">Data da NF (antiga)</option></Select></label></div>
       <div className="invoice-cards">{[...shown.invoices].filter(invoice=>{const contents=shown.materials.filter(m=>invoice.material_ids.includes(m.id));return (!invoiceSearch||[invoice.number,invoice.access_key,...contents.flatMap(m=>[m.sap_code,m.forms_code,m.description])].some(x=>String(x||'').toLowerCase().includes(invoiceSearch.toLowerCase())))&&contents.some(m=>matches(m,invoiceFilters,shown.sites));}).sort((a,b)=>{const total=i=>shown.materials.filter(m=>i.material_ids.includes(m.id)).reduce((s,m)=>s+itemTotal(m),0);switch(invoiceSort){case 'oldest':return String(a.created_at).localeCompare(String(b.created_at));case 'number':return String(a.number).localeCompare(String(b.number),'pt-BR',{numeric:true});case 'value_desc':return total(b)-total(a);case 'value_asc':return total(a)-total(b);case 'date_desc':return String(b.issued_on).localeCompare(String(a.issued_on));case 'date_asc':return String(a.issued_on).localeCompare(String(b.issued_on));default:return String(b.created_at).localeCompare(String(a.created_at))}}).map(invoice=>{const contents=shown.materials.filter(m=>invoice.material_ids.includes(m.id));return <div className="invoice-card" key={invoice.id}><div className="invoice-card-top"><div><span className="eyebrow">NOTA FISCAL</span><h3>NF {invoice.number}</h3><p>Emitida em {dateLabel(invoice.issued_on)} · {contents.length} material(is)</p></div><strong className="invoice-value">{money(contents.reduce((s,m)=>s+itemTotal(m),0))}</strong></div><div className="invoice-tags">{contents.map(m=><span key={m.id} className="invoice-tag"><ProcessTag process={m.process}/>{m.sap_code||m.forms_code} · {m.description||'Material'}</span>)}</div>{invoice.access_key&&<div className="key-row"><span>Chave NF-e: <code>{invoice.access_key}</code></span><button className="icon-button" title="Copiar chave" onClick={()=>navigator.clipboard.writeText(invoice.access_key).then(()=>notify('Chave copiada')).catch(()=>notify('Não foi possível copiar',true))}><Copy size={16}/></button></div>}<div className="invoice-actions">{canWrite&&<><Button variant="secondary" small icon={Pencil} onClick={()=>invoiceModal(invoice)}>Editar nota</Button><Button variant="danger" small icon={Trash2} disabled={busy} onClick={()=>{if(window.confirm(`Excluir NF ${invoice.number}? Os materiais serão desvinculados e retornarão ao status anterior.`))run(()=>deleteInvoice(invoice.id),'Nota excluída, status recalculado')}}>Excluir</Button></>}</div></div>})}</div>{!shown.invoices.length&&<Empty icon={ReceiptText} title="Nenhuma nota fiscal registrada" description="Depois de solicitar no SAP, selecione o bloco para registrar a NF." action={canWrite&&<Button icon={Plus} onClick={()=>invoiceModal()}>Registrar nota</Button>}/>}</section>
   </>}
   {page==='lookup'&&<><Heading eyebrow="LOCALIZAÇÃO RÁPIDA" title="Consulta SAP / Forms" description="Encontre códigos de materiais e seus Forms correspondentes, inclusive ocorrências repetidas."/><section className="panel batch-lookup"><Subhead title="Pesquisar vários Forms de uma vez" description="Cole os números de Forms (um por linha, ou separados por vírgula). Copie o resultado direto para o Excel."/><textarea rows="4" value={formsBatch} onChange={e=>setFormsBatch(e.target.value)} placeholder={'859\n860\n862'}/><div className="batch-bottom"><span className="muted">{formsBatch.split(/[\n,;\t]+/).filter(x=>x.trim()).length} Forms informados</span><Button variant="secondary" icon={Copy} small disabled={!formsBatch.trim()} onClick={()=>{const keys=[...new Set(formsBatch.split(/[\n,;\t]+/).map(x=>x.trim()).filter(Boolean))];const lines=keys.flatMap(f=>{const codes=[...new Set(shown.materials.filter(x=>x.forms_code?.trim().toLowerCase()===f.toLowerCase()).map(x=>x.sap_code).filter(Boolean))];return codes.length?codes.map(c=>`${f}\t${c}`):[`${f}\tNÃO ENCONTRADO`]});navigator.clipboard.writeText('Forms\tCódigo SAP\n'+lines.join('\n')).then(()=>notify('Tabela Forms → SAP copiada')).catch(()=>notify('Não foi possível copiar',true))}}>Copiar Forms + SAP</Button></div>{formsBatch.trim()&&<div className="batch-preview">{[...new Set(formsBatch.split(/[\n,;\t]+/).map(x=>x.trim()).filter(Boolean))].slice(0,30).map(f=><div key={f}><strong>{f}</strong><span>{[...new Set(shown.materials.filter(x=>x.forms_code?.trim().toLowerCase()===f.toLowerCase()).map(x=>x.sap_code).filter(Boolean))].join(', ')||'Não encontrado'}</span></div>)}</div>}</section><section className="panel"><Subhead title="Pesquisar materiais" description={`${filtered.length} resultado(s) — consulta de leitura`} actions={<><ExcelExport filters={filter} sort={sort}/><ExportButton rows={filtered}/><Button variant="secondary" icon={Copy} small disabled={!filtered.length} onClick={()=>navigator.clipboard.writeText([...new Set(filtered.map(x=>x.forms_code).filter(Boolean))].join('\n')).then(()=>notify('Forms copiados')).catch(()=>notify('Falha ao copiar',true))}>Copiar Forms</Button></>}/><Filters value={filter} set={setFilter} sites={shown.sites}/><div className="sort-control standalone"><ArrowUpDown size={15}/><Select value={sort} onChange={setSort}>{SORTS.map(([k,v])=><option value={k} key={k}>{v}</option>)}</Select></div><MaterialTable rows={rows}/><Pagination current={current} pages={pages} total={filtered.length} onPage={setPageno}/></section></>}
   {page==='activity'&&<><Heading eyebrow="RASTREABILIDADE" title="Histórico de alterações" description="Resumo leve de quem alterou, quando e o que mudou, sem duplicar os materiais no banco."/><section className="panel">
    <Subhead title="Atividades recentes" description={`Busca nas 150 atividades mais recentes · ${activityRows.length} resultado(s). Eventos antigos permanecem no Supabase.`}/>
    <div className="auxiliary-filters"><div className="search-field"><Search size={16}/><TextInput value={activitySearch} onChange={setActivitySearch} placeholder="Buscar SAP, Forms, NF ou alteração"/></div><Select aria-label="Tipo de alteração" value={activityKind} onChange={setActivityKind}><option value="">Todas as ações</option><option value="insert">Criado</option><option value="update">Atualizado</option><option value="delete">Excluído</option><option value="status">Mudança de status</option></Select><Select aria-label="Ordenar histórico" value={activitySort} onChange={setActivitySort}><option value="recent">Mais recentes</option><option value="oldest">Mais antigos</option></Select></div>
    <div className="activity-list activity-compact">{activityRows.slice(0,activityShown).map(a=><div className={`activity-entry activity-${a.action}`} key={a.id}><div className="activity-icon"><History size={16}/></div><div className="activity-content"><strong><span className={`activity-kind activity-kind-${a.action}`}>{a.action==='insert'?'Criado':a.action==='update'?'Editado':a.action==='delete'?'Excluído':a.action==='status'?'Status':a.action}</span>{' · '}{a.entity==='materials'||a.entity==='nf_materials'?'Material':a.entity==='invoices'||a.entity==='nf_invoices'?'Nota fiscal':a.entity==='blocks'||a.entity==='nf_blocks'?'Bloco':a.entity}</strong><small>{activityPretty(a.displaySummary)}</small></div><time>{new Date(a.happened_at).toLocaleString('pt-BR')}{a.author_id&&<span className="activity-author" title={a.author_id}> · Usuário {String(a.author_id).slice(0,8)}</span>}</time></div>)}{!activityRows.length&&<Empty icon={History} title="Nenhuma atividade corresponde aos filtros" description="Tente pesquisar por SAP, Forms ou escolha outro tipo de alteração."/>}</div>
    {activityShown<activityRows.length&&<div className="history-pagination"><Button variant="secondary" small onClick={()=>setActivityShown(n=>n+20)}>Mostrar mais {Math.min(20,activityRows.length-activityShown)} eventos</Button><span>{Math.min(activityShown,activityRows.length)} de {activityRows.length}</span></div>}
    <p className="activity-note"><Info size={14}/> Nenhuma cópia completa dos materiais é salva no histórico. As alterações antigas não são apagadas.</p>
   </section></>}
   {page==='settings'&&<><Heading eyebrow="ADMINISTRAÇÃO" title="Configurações" description="Gerencie os sites e verifique a conexão e permissões do ambiente."/><div className="settings-grid"><section className="panel"><Subhead title="Sites e centros" description="Localidades disponíveis no cadastro de materiais." actions={canWrite&&<Button small icon={Plus} onClick={()=>setModal({kind:'site'})}>Adicionar site</Button>}/><div className="auxiliary-filters"><div className="search-field"><Search size={16}/><TextInput value={siteSearch} onChange={setSiteSearch} placeholder="Pesquisar site, centro, transportadora ou região"/></div></div><div className="site-list">{[...shown.sites].filter(s=>!siteSearch||[s.name,s.center_code,s.region,s.carrier_info].some(v=>String(v||'').toLowerCase().includes(siteSearch.toLowerCase()))).sort((a,b)=>a.name.localeCompare(b.name)).map(s=><div key={s.id} className="site-row"><div className="site-icon"><MapPin size={18}/></div><div><strong>{s.name}</strong><small>{s.region||'Sem região'} · {s.center_code||'Sem centro'}</small></div>{canWrite&&<div className="inline-buttons"><button className="icon-button" onClick={()=>setModal({kind:'site',record:s})} title="Editar site"><Pencil size={16}/></button><button className="icon-button" onClick={()=>removeConfirm('sites',s,`o site ${s.name}`)} title="Excluir site"><Trash2 size={16}/></button></div>}</div>)}{!shown.sites.length&&<Empty icon={MapPin} title="Nenhum site cadastrado" description="Cadastre um site para começar a lançar materiais."/>}</div></section><section className="panel"><Subhead title="Ambiente e acesso"/><div className="setting-detail"><span>Armazenamento</span><strong>{cloud?'Supabase PostgreSQL':'Demonstração local'}</strong></div><div className="setting-detail"><span>Permissão atual</span><strong>{canWrite?'Administrador':'Visualizador'}</strong></div><div className="setting-detail"><span>Banco</span><strong>{cloud?'NotaFlow 2 · nf_*':'Dados apenas neste navegador'}</strong></div><div className="notice"><ShieldCheck size={20}/><span>{cloud?'Dados protegidos pelas políticas RLS do Supabase. Usuários visualizadores não podem editar pelo aplicativo nem pela API.':'O modo demonstração salva no navegador. Para compartilhar os dados, configure um Supabase novo conforme o README.'}</span></div>{!cloud&&<Button variant="danger" icon={Trash2} onClick={()=>{if(window.confirm('Apagar TODOS os dados do modo demonstração deste navegador?')){localStorage.removeItem('notaflow-v2-demo-v1');location.reload();}}}>Zerar demonstração</Button>}</section></div>{cloud&&canWrite&&<StoragePanel usage={dbUsage} onRefresh={refreshDbUsage}/>}</>}
  </main></div>
  {toast&&<div className={`toast ${toast.error?'toast-error':''}`} key={toast.at}><div>{toast.error?<AlertCircle size={19}/>:<CheckCircle2 size={19}/>}<span>{toast.message}</span></div><button className="icon-button" onClick={()=>setToast(null)} aria-label="Fechar aviso"><X size={15}/></button></div>}
  {modal?.kind==='material'&&<MaterialEditor record={modal.record} sites={shown.sites} blocks={orderedBlocks} busy={busy} onClose={()=>setModal(null)} onSave={r=>run(()=>saveRow('materials',r),'Material salvo')} onDelete={r=>{if(r.invoice_id)return notify('Desvincule a nota antes de excluir',true);if(window.confirm('Excluir material?'))run(()=>deleteRow('materials',r.id),'Material excluído')}}/>}
  {modal?.kind==='import'&&<ImportEditor sites={shown.sites} blocks={orderedBlocks} busy={busy} onClose={()=>setModal(null)} onSave={r=>run(()=>saveManyMaterials(r),`${r.length} materiais importados`)}/>}
  {modal?.kind==='invoice'&&<InvoiceEditor invoice={modal.record} materials={shown.materials} blocks={orderedBlocks} startBlockId={modal.blockId||''} busy={busy} onClose={()=>setModal(null)} onSave={(form,ids)=>run(()=>saveInvoice(form,ids),'Nota fiscal salva; status atualizado')}/>}
  {modal?.kind==='block'&&<NameEditor title={modal.record?'Editar bloco':'Criar bloco'} record={modal.record} onClose={()=>setModal(null)} onSave={value=>run(()=>saveRow('blocks',{...(modal.record?.id?{id:modal.record.id}:{}),name:value,auto_created:false,position:modal.record?.position??Math.max(-1,...orderedBlocks.map(b=>Number(b.position)||0))+1}),'Bloco salvo')} busy={busy}/>}
  {modal?.kind==='site'&&<SiteEditor record={modal.record} busy={busy} onClose={()=>setModal(null)} onSave={value=>run(()=>saveRow('sites',value),'Site salvo')}/>}
 </div>;
}
function Stat({icon:Icon,label,value,detail,accent=false}){return <div className={`stat-card ${accent?'stat-accent':''}`}><div className="stat-top"><span>{label}</span><div className="stat-icon"><Icon size={19}/></div></div><strong>{value}</strong><small>{detail}</small></div>}
function Pagination({current,pages,total,onPage}){return <div className="pagination"><span>{total} registro(s) · Página {current} de {pages}</span><div><button className="icon-button" aria-label="Página anterior" disabled={current<=1} onClick={()=>onPage(current-1)}><ChevronLeft size={18}/></button><button className="icon-button" aria-label="Próxima página" disabled={current>=pages} onClick={()=>onPage(current+1)}><ChevronRight size={18}/></button></div></div>}
function NameEditor({title,record,onClose,onSave,busy}){const [name,setName]=useState(record?.name||'');return <Modal title={title} onClose={onClose}><form onSubmit={e=>{e.preventDefault();if(name.trim())onSave(name)}}><Field label="Nome do bloco"><TextInput value={name} onChange={setName} autoFocus required maxLength={80} placeholder="Ex.: BLOCO 001 — CNC"/></Field><div className="modal-actions"><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" icon={Save} disabled={busy||!name.trim()}>Salvar bloco</Button></div></form></Modal>}
function SiteEditor({record,onClose,onSave,busy}){const [r,setR]=useState({name:'',region:'',center_code:'',carrier_info:'',...record});const set=(k,v)=>setR(p=>({...p,[k]:v}));return <Modal title={record?'Editar site':'Adicionar site'} onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave({...(record?.id?{id:record.id}:{}),name:r.name.trim(),region:r.region,center_code:r.center_code,carrier_info:r.carrier_info})}}><div className="form-grid"><div className="span-2"><Field label="Nome"><TextInput value={r.name} onChange={v=>set('name',v)} required autoFocus placeholder="Ex.: Valinhos"/></Field></div><Field label="Região"><TextInput value={r.region} onChange={v=>set('region',v)} placeholder="Ex.: Sudeste"/></Field><Field label="Centro"><TextInput value={r.center_code} onChange={v=>set('center_code',v)} placeholder="Código ou descrição"/></Field><div className="span-2"><Field label="Transportadora / observações"><TextInput value={r.carrier_info} onChange={v=>set('carrier_info',v)}/></Field></div></div><div className="modal-actions"><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" icon={Save} disabled={busy||!r.name.trim()}>Salvar site</Button></div></form></Modal>}
